/** Inline brand mark sized by the surrounding .set-provider-logo container. */
export function ProviderLogo({ id }: { id: string }) {
  return (
    <span className="set-provider-logo" aria-hidden="true">
      {LOGOS[id as AiProviderId] ?? LOGOS.custom}
    </span>
  )
}
